#include "chronus1/loader.h"
#include "chronus1/trap.h"
#include <algorithm>
#include <fstream>
#include <set>
namespace chronus1 {
static uint32_t crc32(const uint8_t*p,size_t n){uint32_t c=~0u;for(size_t i=0;i<n;i++){c^=p[i];for(int k=0;k<8;k++)c=(c>>1)^(0xedb88320u&uint32_t(-int(c&1)));}return~c;}
static uint16_t u16(const std::vector<uint8_t>&b,size_t o){return uint16_t(b[o])|uint16_t(b[o+1])<<8;}static uint32_t u32(const std::vector<uint8_t>&b,size_t o){return uint32_t(b[o])|uint32_t(b[o+1])<<8|uint32_t(b[o+2])<<16|uint32_t(b[o+3])<<24;}
uint32_t Binary::reconvergence_pc(uint32_t pc)const{for(auto&r:reconvergence)if(r.first==pc)return r.second;trap(TrapCode::BinaryFormat,"divergent branch lacks reconvergence metadata");}
Binary load_binary(const std::filesystem::path&p){std::ifstream f(p,std::ios::binary);if(!f)trap(TrapCode::BinaryFormat,"cannot open executable");std::vector<uint8_t>b((std::istreambuf_iterator<char>(f)),{});if(b.size()<32||std::string((char*)b.data(),4)!="CHRN")trap(TrapCode::BinaryFormat,"bad CHRN header");Binary x;x.major=u16(b,4);x.minor=u16(b,6);x.flags=u32(b,8);x.entry=u32(b,12);auto words=u32(b,16);x.global_bytes=u32(b,20);auto checksum=u32(b,24);auto meta_bytes=u32(b,28);size_t code_bytes=size_t(words)*4;if(x.major!=1||x.minor<1||x.flags||b.size()!=32+code_bytes+meta_bytes||x.entry%4||x.entry/4>=std::max(1u,words))trap(TrapCode::BinaryFormat,"unsupported binary layout");if(crc32(b.data()+32,b.size()-32)!=checksum)trap(TrapCode::BinaryFormat,"container checksum mismatch");for(size_t o=32;o<32+code_bytes;o+=4)x.code.push_back(u32(b,o));size_t off=32+code_bytes,end=off+meta_bytes;if(meta_bytes<16||std::string((char*)b.data()+off,4)!="META")trap(TrapCode::BinaryFormat,"missing metadata");auto ns=u32(b,off+4),nr=u32(b,off+8);if(u32(b,off+12))trap(TrapCode::BinaryFormat,"metadata reserved field nonzero");off+=16;std::set<std::string>names;std::set<uint32_t>branches;for(uint32_t i=0;i<ns;i++){if(off+12>end)trap(TrapCode::BinaryFormat,"truncated symbol");uint16_t n=u16(b,off);uint8_t kind=b[off+2],flags=b[off+3];uint32_t value=u32(b,off+4),size=u32(b,off+8);off+=12;size_t padded=(n+3u)&~3u;if(!n||n>255||off+padded>end)trap(TrapCode::BinaryFormat,"invalid symbol");std::string name((char*)b.data()+off,n);for(size_t j=n;j<padded;j++)if(b[off+j])trap(TrapCode::BinaryFormat,"noncanonical symbol padding");off+=padded;if(!names.insert(name).second)trap(TrapCode::BinaryFormat,"duplicate symbol");x.symbols.push_back({name,value,size,kind,flags});}for(uint32_t i=0;i<nr;i++){if(off+8>end)trap(TrapCode::BinaryFormat,"truncated reconvergence");uint32_t branch=u32(b,off),target=u32(b,off+4);off+=8;if(branch%4||target%4||branch/4>=words||target/4>=words||!branches.insert(branch).second)trap(TrapCode::BinaryFormat,"invalid reconvergence record");x.reconvergence.push_back({branch,target});}if(off!=end)trap(TrapCode::BinaryFormat,"trailing metadata bytes");return x;}
void write_binary(const std::filesystem::path&p,const Binary&x){if(x.major!=1||x.minor<1||x.flags||x.entry%4||x.entry/4>=std::max<size_t>(1,x.code.size()))trap(TrapCode::BinaryFormat,"cannot encode invalid executable");std::vector<uint8_t>meta(16);auto append16=[&](uint16_t v){meta.push_back(v);meta.push_back(v>>8);};auto append32=[&](uint32_t v){for(int i=0;i<4;i++)meta.push_back(v>>(8*i));};meta[0]='M';meta[1]='E';meta[2]='T';meta[3]='A';auto set32=[&](size_t o,uint32_t v){for(int i=0;i<4;i++)meta[o+i]=v>>(8*i);};set32(4,x.symbols.size());set32(8,x.reconvergence.size());std::set<std::string>names;for(auto&s:x.symbols){if(s.name.empty()||s.name.size()>255||!names.insert(s.name).second)trap(TrapCode::BinaryFormat,"invalid symbol");append16(s.name.size());meta.push_back(s.kind);meta.push_back(s.flags);append32(s.value);append32(s.size);meta.insert(meta.end(),s.name.begin(),s.name.end());while(meta.size()%4)meta.push_back(0);}std::set<uint32_t>branches;for(auto&r:x.reconvergence){if(r.first%4||r.second%4||r.first/4>=x.code.size()||r.second/4>=x.code.size()||!branches.insert(r.first).second)trap(TrapCode::BinaryFormat,"invalid reconvergence");append32(r.first);append32(r.second);}std::vector<uint8_t>payload(x.code.size()*4+meta.size());for(size_t j=0;j<x.code.size();j++)for(int i=0;i<4;i++)payload[j*4+i]=x.code[j]>>(8*i);std::copy(meta.begin(),meta.end(),payload.begin()+x.code.size()*4);std::vector<uint8_t>b(32);b[0]='C';b[1]='H';b[2]='R';b[3]='N';auto w16=[&](size_t o,uint16_t v){b[o]=v;b[o+1]=v>>8;};auto w32=[&](size_t o,uint32_t v){for(int i=0;i<4;i++)b[o+i]=v>>(8*i);};w16(4,x.major);w16(6,x.minor);w32(8,x.flags);w32(12,x.entry);w32(16,x.code.size());w32(20,x.global_bytes);w32(24,crc32(payload.data(),payload.size()));w32(28,meta.size());b.insert(b.end(),payload.begin(),payload.end());std::ofstream f(p,std::ios::binary);if(!f)trap(TrapCode::BinaryFormat,"cannot write executable");f.write((char*)b.data(),b.size());}
}
